import { useCallback, useMemo } from 'react';

import { BrandImg } from 'components/BrandImg/BrandImg';
import { useQuickFilter } from 'components/Filter/hooks/useQuickFilter';
import { FieldProps } from 'components/Filter/types';
import { filterCommercialSelectOptions } from 'components/Filter/utils/commercialSelectOptions';
import { Select } from 'components/Form';
import {
  hasActiveQuickFilterValue,
  isPerformanceToolFilterPage,
} from 'domain/Filter/brandSubBrandQuickFilterPolicy';
import { usePageFilterManagement } from 'hooks';
import { Option } from 'models/Filters';
import { getBrandImagePlaceholderUrl } from 'utils';

export const BrandsQuickFilter = ({
  dataTestId,
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
}: FieldProps) => {
  const { updateForm } = usePageFilterManagement(pageName);
  const countryValue = getCurrentValue('country');
  const brandValue = getCurrentValue('brands');
  const brandGroupingsValue = getCurrentValue('brand_filter_groupings');

  const brandsFilter = useQuickFilter({
    fieldKey,
    pageName,
    gaCategory: 'Brand Select',
    filterContext: { country: countryValue },
    onValueChange,
    getCurrentValue,
  });

  const activeOptions = useMemo(
    () => filterCommercialSelectOptions(pageName, brandsFilter.options),
    [pageName, brandsFilter.options],
  );

  const isAllValue = (value: unknown): boolean => {
    if (value == null || value === '') return true;
    if (typeof value === 'string') return value.toUpperCase() === 'ALL';
    if (typeof value === 'object' && value !== null && 'value' in value) {
      const optionValue = (value as Option).value;
      if (optionValue == null || optionValue === '') return true;
      return String(optionValue).toUpperCase() === 'ALL';
    }
    return false;
  };

  const shouldHideBrandsFilter = useMemo(() => {
    if (isPerformanceToolFilterPage(pageName)) {
      return countryValue === 'ABI' && brandGroupingsValue !== 'All Brands';
    }
    return false;
  }, [countryValue, brandGroupingsValue, pageName]);

  const isEmptyBrandChip = isAllValue(brandValue);

  const resolvedSelectValue = useMemo(() => {
    if (!isEmptyBrandChip) {
      return brandsFilter.currentValue;
    }

    const allOption = activeOptions.find(
      (option) => String(option.value).toUpperCase() === 'ALL',
    );

    return allOption ?? { value: 'All', label: 'All' };
  }, [activeOptions, brandsFilter.currentValue, isEmptyBrandChip]);

  const canClear = isEmptyBrandChip ? false : brandsFilter.showClearIcon;

  const handleBrandSelect = useCallback(
    (option: Option) => {
      const portfolioValue = getCurrentValue('portfolios');

      if (
        !hasActiveQuickFilterValue(portfolioValue) &&
        isPerformanceToolFilterPage(pageName)
      ) {
        updateForm('brand_filter_groupings', 'All Brands');
      }

      brandsFilter.handleValueChange(option);
    },
    [brandsFilter, getCurrentValue, pageName, updateForm],
  );

  const getChipPlaceholder = useCallback(
    (options: Option | Option[]) => {
      const option = Array.isArray(options) ? options[0] : options;

      return (
        <BrandImg
          src={option?.image_url || getBrandImagePlaceholderUrl()}
          alt={String(option?.label || option?.value || '')}
          dataTestId={dataTestId ? `${dataTestId}-brand-img` : undefined}
          width="16px"
          height="16px"
        />
      );
    },
    [dataTestId],
  );

  if (shouldHideBrandsFilter) {
    return null;
  }

  return (
    <Select
      dataTestId={dataTestId ? `${dataTestId}-${fieldKey}` : undefined}
      id={`${fieldKey}-select-quick-filter`}
      value={resolvedSelectValue}
      options={activeOptions}
      showChip={!isEmptyBrandChip}
      showValueSelected={!isEmptyBrandChip}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        handleBrandSelect(opt as Option);
      }}
      size="medium"
      shape="pill"
      fitContent
      menuFitContent
      placeholder=""
      chips
      clearChips={canClear}
      onClearSingle={brandsFilter.handleClear}
      valueLabel="Brand"
      getChipPlaceholder={isEmptyBrandChip ? undefined : getChipPlaceholder}
      searchable
    />
  );
};
